import { createElement } from "react";
import type { Meta, StoryObj } from "@storybook/react-vite";
import elementsSource from "@creator-signal/design-system/elements.json";

type Disposition = "styled" | "native-only" | "conditional" | "reference-only";
type ElementEntry = {
  name: string;
  label: string;
  disposition: Disposition;
  summary: string;
  accessibility: string;
};
type Category = {
  id: string;
  label: string;
  description: string;
  use: string;
  avoid: string;
  content: string;
  accessibility: string;
  elements: ElementEntry[];
};

const registry = elementsSource as {
  definition: string;
  owner: string;
  stylesheet: string;
  dispositions: Record<string, string>;
  categories: Category[];
  inputTypes: string[];
  foreignContent: Array<{ name: string; disposition: "not-applicable"; summary: string }>;
  obsoleteElements: Array<{ name: string; disposition: "prohibited"; replacement: string }>;
};

const categoryById = new Map(registry.categories.map((category) => [category.id, category]));
const referenceOnly = new Set(["html", "head", "title", "base", "link", "meta", "style", "body", "main", "script", "noscript", "template", "slot"]);

function escapeText(value: string) {
  return value.replaceAll("&", "&amp;").replaceAll("<", "&lt;").replaceAll(">", "&gt;");
}

