function DispositionBadge({ disposition }: { disposition: string }) {
  return <span className={`cs-element-disposition cs-element-disposition--${disposition}`}>{disposition}</span>;
}

function ElementCard({ category, entry }: { category: Category; entry: ElementEntry }) {
  const markup = exampleMarkup(entry.name);
  const canRender = !referenceOnly.has(entry.name);
  return (
    <article className="cs-element-card" id={`element-${entry.name}`}>
      <header className="cs-element-card-header">
        <div>
          <code>&lt;{entry.name}&gt;</code>
          <h2>{entry.label}</h2>
        </div>
        <DispositionBadge disposition={entry.disposition} />
      </header>
      <p className="cs-element-definition">{entry.summary}</p>
      <section aria-label={`${entry.label} live example`} className="cs-element-live">
        <span className="cs-element-eyebrow">{canRender ? "Live HTML" : "Document infrastructure"}</span>
        {canRender
          ? <div dangerouslySetInnerHTML={{ __html: markup }} />
          : <p>This element belongs to the document or component infrastructure and is shown as source rather than nested invalid markup.</p>}
      </section>
      <div className="cs-element-guidance-grid">
        <div><strong>Use</strong><p>{category.use}</p></div>
        <div><strong>Do not use</strong><p>{category.avoid}</p></div>
        <div><strong>Content</strong><p>{category.content}</p></div>
        <div><strong>Accessibility</strong><p>{entry.accessibility}</p></div>
      </div>
      <details className="cs-element-source">
        <summary>HTML source</summary>
        <pre><code>{markup}</code></pre>
      </details>
      <footer className="cs-element-card-footer">
        <span>Owner: {registry.owner}</span>
        <span>Style source: {registry.stylesheet}</span>
      </footer>
    </article>
  );
}

function CoverageMatrix() {
  const elements = registry.categories.flatMap((category) => category.elements);
  const counts = Object.keys(registry.dispositions).map((disposition) => ({
    disposition,
    count: elements.filter((element) => element.disposition === disposition).length
      + registry.obsoleteElements.filter((element) => element.disposition === disposition).length
      + registry.foreignContent.filter((element) => element.disposition === disposition).length
  }));
  return (
    <dl className="cs-elements-counts">
      <div><dt>Living HTML elements</dt><dd>{elements.length}</dd></div>
      <div><dt>Input types</dt><dd>{registry.inputTypes.length}</dd></div>
      <div><dt>Obsolete prohibited</dt><dd>{registry.obsoleteElements.length}</dd></div>
      {counts.filter(({ count }) => count > 0).map(({ disposition, count }) => (
        <div key={disposition}><dt>{disposition}</dt><dd>{count}</dd></div>
      ))}
    </dl>
  );
}

function ElementsOverview() {
  return (
    <main className="cs-dls-shell cs-elements cs-elements-reference">
      <header className="cs-elements-hero">
        <p className="cs-dls-kicker">DLS · Elements</p>
        <h1>Semantic HTML before components.</h1>
        <p>{registry.definition}</p>
        <CoverageMatrix />
      </header>

      <section className="cs-elements-principle" aria-labelledby="elements-order-title">
        <div><span>01</span><h2 id="elements-order-title">Meaning</h2><p>Choose the native element whose semantics match the content or action.</p></div>
        <div><span>02</span><h2>Presentation</h2><p>Opt into the Elements stylesheet for shared rhythm, focus and native-control treatment.</p></div>
        <div><span>03</span><h2>Composition</h2><p>Reach for a Component or Widget only when reusable API, state or behaviour is required.</p></div>
      </section>

      <section className="cs-elements-inventory" aria-labelledby="elements-inventory-title">
        <div className="cs-dls-section-heading">
          <div><p className="cs-dls-card-label">Complete inventory</p><h2 id="elements-inventory-title">Every category is explicit</h2></div>
          <p>Nothing becomes a component merely because it appears here. Each category links semantics, source, content rules and accessibility.</p>
        </div>
        <div className="cs-elements-category-grid">
          {registry.categories.map((category) => (
            <article key={category.id}>
              <span>{String(category.elements.length).padStart(2, "0")}</span>
              <h3>{category.label}</h3>
              <p>{category.description}</p>
              <p className="cs-elements-tag-list">{category.elements.map(({ name }) => `<${name}>`).join(" · ")}</p>
            </article>
          ))}
        </div>
      </section>

      <section className="cs-elements-boundary" aria-labelledby="element-boundary-title">
        <div><p className="cs-dls-card-label">Authority boundary</p><h2 id="element-boundary-title">Raw HTML is not the whole interface system</h2></div>
        <dl>
          <div><dt>Element</dt><dd>Native structure, semantics and baseline presentation.</dd></div>
          <div><dt>Component</dt><dd>Reusable API and accessible behaviour owned by @creator-signal/ui.</dd></div>
          <div><dt>Widget</dt><dd>Multiple elements or components coordinated around one task.</dd></div>
          <div><dt>Experience</dt><dd>A complete outcome-led journey owned by its application or adapter.</dd></div>
        </dl>
      </section>
    </main>
  );
}

function CategoryPage({ id, direction }: { id: string; direction?: "ltr" | "rtl" }) {
  const category = categoryById.get(id);
  if (!category) throw new Error(`Unknown Elements category: ${id}`);
  return (
    <main className="cs-dls-shell cs-elements cs-elements-reference" dir={direction ?? (id === "inline" ? "auto" : undefined)}>
      <header className="cs-elements-category-header">
        <p className="cs-dls-kicker">DLS · Elements · {category.label}</p>
        <h1>{category.label}</h1>
        <p>{category.description}</p>
        <div className="cs-elements-acceptance" aria-label="Reference acceptance coverage">
