};

const registry = experienceSource as Registry;
const categoryById = new Map(registry.categories.map((category) => [category.id, category]));
const sourceBase = "https://github.com/creator-signal/sales-pulse/blob/develop/";

function initialParam(name: string, allowed: string[], fallback: string) {
  if (typeof window === "undefined") return fallback;
  const value = new URL(window.location.href).searchParams.get(name);
  return value && allowed.includes(value) ? value : fallback;
}

function updateDeepLink(values: Record<string, string>) {
  if (typeof window === "undefined") return;
  const url = new URL(window.location.href);
  for (const [key, value] of Object.entries(values)) url.searchParams.set(key, value);
  window.history.replaceState(null, "", url);
}

function isolatedUrl(values: Record<string, string>) {
  if (typeof window === "undefined") return "#";
  const url = new URL(window.location.href);
  url.pathname = url.pathname.replace(/[^/]*$/, "iframe.html");
  url.search = "";
  url.searchParams.set("id", "dls-experiences--workbench");
  url.searchParams.set("viewMode", "story");
  for (const [key, value] of Object.entries(values)) url.searchParams.set(key, value);
  return url.toString();
}

function SelectControl({ label, onChange, options, value }: { label: string; onChange: (value: string) => void; options: string[]; value: string }) {
  const id = `experience-${label.toLowerCase().replace(/[^a-z]+/g, "-")}`;
  return <label htmlFor={id}><span>{label}</span><select id={id} onChange={(event) => onChange(event.target.value)} value={value}>{options.map((option) => <option key={option} value={option}>{option.replaceAll("-", " ")}</option>)}</select></label>;
}

function StatePreview({ content, experience, media, refreshKey, state }: { content: string; experience: Experience; media: string; refreshKey: number; state: string }) {
  const isLong = content === "long";
  const detail = isLong
    ? "This deliberately extended synthetic explanation proves that headings, controls, evidence and recovery guidance reflow without hiding meaning or requiring horizontal page scrolling."
    : "Synthetic reference content. No route, provider, customer record or write is connected.";
  const includeImage = experience.category === "marketing-public" || experience.category === "communication";
  if (state === "loading" || state === "delayed") return <Card><StatusIndicator tone="info">{state === "loading" ? "Loading" : "Taking longer than expected"}</StatusIndicator><h2>{experience.label}</h2><p>{detail}</p><Button variant="secondary">Cancel safely</Button></Card>;
  if (state === "empty") return <EmptyState title={`No ${experience.label.toLowerCase()} evidence yet`} description={detail} actions={<Button>Create synthetic example</Button>} />;
  if (state === "error" || state === "provider-unavailable") return <ErrorState title={state === "error" ? "The outcome could not be completed" : "The provider is unavailable"} description={detail} retry={<Button variant="secondary">Try again</Button>} />;
  const tone = state === "success" ? "success" : state === "warning" || state === "payment" || state === "entitlement" || state === "verification" ? "warning" : "info";
  return <Card key={refreshKey}>
    <Badge tone={tone}>{state.replaceAll("-", " ")}</Badge>
    <h2>{experience.label}</h2>
    <p>{experience.outcome}</p>
    {includeImage ? <figure><img alt="Synthetic experience artwork" src={media === "blocked-image" ? referencePath("/missing-experience-artwork.svg") : referencePath("/brand-assets/delivery/creator-signal-logo-horizontal/light-background.svg")} /><figcaption>Meaning remains in this caption when the image is blocked.</figcaption></figure> : null}
    <StatGroup><Stat label="Evidence" value="12" context="Invented records" /><Stat label="Confidence" value="High" context="Synthetic demonstration" /></StatGroup>
    <Notice heading={state === "recovery" ? "Recovery is available" : "Review before acting"} tone={tone}><p>{detail}</p></Notice>
    <Button>{state === "permission" ? "Request access" : state === "verification" ? "Continue verification" : state === "payment" ? "Review payment" : "Review evidence"}</Button>
  </Card>;
}

function LayerTrace({ label, values }: { label: string; values: string[] }) {
  return <section><h3>{label}</h3>{values.length ? <ul>{values.map((value) => <li key={value}><code>{value}</code></li>)}</ul> : <p>Not required by this Experience.</p>}</section>;
}

