function ExperienceWorkbench() {
  const [experienceId, setExperienceId] = useState(() => initialParam("experience", registry.experiences.map(({ id }) => id), registry.experiences[0]!.id));
  const experience = useMemo(() => registry.experiences.find(({ id }) => id === experienceId) ?? registry.experiences[0]!, [experienceId]);
  const [tab, setTab] = useState<WorkbenchTab>(() => initialParam("tab", registry.controls.tabs, "preview") as WorkbenchTab);
  const [viewport, setViewport] = useState(() => initialParam("viewport", registry.controls.viewports, "desktop"));
  const [theme, setTheme] = useState(() => initialParam("theme", registry.controls.themes, "system"));
  const [media, setMedia] = useState(() => initialParam("media", registry.controls.media, "loaded"));
  const [content, setContent] = useState(() => initialParam("content", registry.controls.content, "standard"));
  const [direction, setDirection] = useState(() => initialParam("direction", registry.controls.directions, "ltr"));
  const [state, setState] = useState(() => initialParam("state", experience.states, experience.states[0]!));
  const [refreshKey, setRefreshKey] = useState(0);
  useEffect(() => { if (!experience.states.includes(state)) setState(experience.states[0]!); }, [experience, state]);
  useEffect(() => updateDeepLink({ experience: experience.id, tab, viewport, theme, media, content, direction, state }), [experience.id, tab, viewport, theme, media, content, direction, state]);
  const deepLinkValues = { experience: experience.id, tab, viewport, theme, media, content, direction, state };
  return (
    <main className="cs-dls-shell cs-experience-workbench" data-experience-id={experience.id}>
      <header className="cs-component-hero"><p className="cs-dls-kicker">DLS · Experiences · Workbench</p><h1>{experience.label}</h1><p>{experience.outcome}</p><div className="cs-component-meta"><span>{categoryById.get(experience.category)?.label}</span><span>{experience.maturity}</span><span>{experience.sourceKind}</span><span>Issue #1412</span></div></header>
      <section aria-label="Experience controls" className="cs-experience-controls">
        <SelectControl label="Experience" onChange={(value) => { setExperienceId(value); setState(registry.experiences.find(({ id }) => id === value)!.states[0]!); }} options={registry.experiences.map(({ id }) => id)} value={experience.id} />
        <SelectControl label="Viewport" onChange={setViewport} options={registry.controls.viewports} value={viewport} />
        <SelectControl label="Theme" onChange={setTheme} options={registry.controls.themes} value={theme} />
        <SelectControl label="Media" onChange={setMedia} options={registry.controls.media} value={media} />
        <SelectControl label="State" onChange={setState} options={experience.states} value={state} />
        <SelectControl label="Content" onChange={setContent} options={registry.controls.content} value={content} />
        <SelectControl label="Direction" onChange={setDirection} options={registry.controls.directions} value={direction} />
        <div className="cs-experience-control-actions"><Button onClick={() => setRefreshKey((value) => value + 1)} variant="secondary">Refresh preview</Button><a className="cs-ui-button cs-ui-button--secondary" href={isolatedUrl(deepLinkValues)} rel="noreferrer" target="_blank">Open isolated preview</a></div>
      </section>
      <Tabs defaultValue="preview" onValueChange={(value) => setTab(value as WorkbenchTab)} value={tab}>
        <TabList label="Experience workbench views">{registry.controls.tabs.map((value) => <Tab key={value} value={value}>{value === "code-source" ? "Code / Source" : value[0]!.toUpperCase() + value.slice(1)}</Tab>)}</TabList>
        <TabPanel value="preview"><section aria-label={`${experience.label} synthetic preview`} className={`cs-experience-preview cs-experience-preview--${viewport}`} data-content={content} data-cs-theme={theme === "system" ? undefined : theme} data-direction={direction} data-media={media} data-theme-preference={theme} dir={direction}><div className="cs-experience-preview__boundary"><p><strong>Synthetic reference:</strong> this is not the {experience.owner} runtime and performs no provider action or write.</p></div><StatePreview content={content} experience={experience} media={media} refreshKey={refreshKey} state={state} /></section></TabPanel>
        <TabPanel value="composition"><section className="cs-experience-panel"><h2>Composition trace</h2><p>Every ID resolves to its governed layer. No consumer-owned Accordion is claimed.</p><div className="cs-experience-layer-grid"><LayerTrace label="Elements" values={experience.composition.elements} /><LayerTrace label="Components" values={experience.composition.components} /><LayerTrace label="Widgets" values={experience.composition.widgets} /><LayerTrace label="Patterns" values={experience.composition.patterns} /></div><h3>Content slots</h3><ul>{experience.contentSlots.map((slot) => <li key={slot}>{slot}</li>)}</ul><h3>States</h3><p>{experience.states.join(" · ")}</p></section></TabPanel>
        <TabPanel value="code-source"><section className="cs-experience-panel"><h2>Authoritative source</h2><Notice heading="Source links, not invented snippets" tone="info"><p>The reference never emits a copy-paste implementation. Open the owning source and its existing rendered projection.</p></Notice><ul>{experience.sourcePaths.map((path) => <li key={path}><a href={`${sourceBase}${path}`} rel="noreferrer" target="_blank"><code>{path}</code></a></li>)}</ul><p><a href={`?path=/story/${experience.storyId}`}>Open the existing source-controlled projection</a></p></section></TabPanel>
        <TabPanel value="adoption"><section className="cs-experience-panel"><h2>Adoption and ownership</h2><KeyValueList><KeyValueItem label="Owner" value={experience.owner} /><KeyValueItem label="Source kind" value={experience.sourceKind} /><KeyValueItem label="Maturity" value={experience.maturity} /><KeyValueItem label="Variants" value={experience.variants.join(", ")} /><KeyValueItem label="Supporting projections" value={experience.projections.join(", ")} /></KeyValueList><h3>Boundaries</h3><dl className="cs-experience-boundaries">{Object.entries(experience.boundaries).map(([key, value]) => <div key={key}><dt>{key}</dt><dd>{value}</dd></div>)}</dl>{experience.formSurfaceIds?.length ? <p><strong>Form surfaces:</strong> {experience.formSurfaceIds.join(", ")}</p> : null}{experience.emailSurfaceIds?.length ? <p><strong>Email surfaces:</strong> {experience.emailSurfaceIds.join(", ")}</p> : null}<p><strong>Related alternatives:</strong> {experience.relatedAlternatives.join(", ")}</p></section></TabPanel>
      </Tabs>
    </main>
  );
}

