function burst() { if (!document.hidden) confetti({position:{x:innerWidth*Math.random(),y:innerHeight*.25},count:55,velocity:110,fade:true}); }
burst(); setInterval(burst, 1100);
</script></body></html>`;

const setup = [
  { title: "Pin your Helper", summary: "A helping hand, always within reach.", detail: "Open your browser’s Extensions menu and pin Sales Pulse Helper. Its icon lets you show or hide the toolbar and reopen the welcome." },
  { title: "Connect Creator Signal", summary: "Give your shop a place to shine.", detail: "Open the Helper extension icon and sign in to Creator Signal. Check that you have selected the right workspace. Installation alone does not connect your account." },
  { title: "Meet us on Spoonflower", summary: "Your new Helper will meet you there.", detail: "Open Spoonflower and sign in to your shop. The welcome introduces your toolbar, visibility settings and import activity. You stay in control of setup." }
];
function HelperInstalled({ confettiBackground = false, centralPanel = true }: { confettiBackground?: boolean; centralPanel?: boolean }) {
  const [reducedMotion, setReducedMotion] = useState(() => window.matchMedia("(prefers-reduced-motion: reduce)").matches);
  const [paused, setPaused] = useState(false);
  useEffect(() => {
    const media = window.matchMedia("(prefers-reduced-motion: reduce)");
    const update = () => setReducedMotion(media.matches);
    media.addEventListener("change", update);
    return () => media.removeEventListener("change", update);
  }, []);
  const { resolvedTheme } = useTheme();
  const [active, setActive] = useState<number | null>(null);
  const guide = useRef<HTMLDivElement>(null);
  const start = () => { setActive(0); requestAnimationFrame(() => { guide.current?.focus({ preventScroll: true }); guide.current?.scrollIntoView({ block: "nearest" }); }); };
  return <main className={`cs-install${confettiBackground ? " cs-install--animated" : ""}${confettiBackground && centralPanel ? " cs-install--confetti" : ""}`}>
    {confettiBackground && !paused && !reducedMotion && <iframe className="cs-install-confetti-background" title="Decorative confetti" aria-hidden="true" tabIndex={-1} sandbox="allow-scripts" srcDoc={confettiDocument.replace("html,body{", `html,body{color-scheme:${resolvedTheme};`)} />}
    <header className="cs-install-header"><strong>Sales Pulse Helper</strong><Badge tone="warning">Planned · installation preview</Badge>{confettiBackground && <Button variant="ghost" disabled={reducedMotion} onClick={() => setPaused(!paused)}>{reducedMotion ? "Motion reduced" : paused ? "Resume confetti" : "Pause confetti"}</Button>}</header>
    <div className="cs-install-panel">
    <section className="cs-install-hero" aria-labelledby="installed-title">
      <div className="cs-install-celebration" aria-hidden="true">
        {!confettiBackground && Array.from({ length: 12 }, (_, index) => <i key={index} style={{ "--piece": index } as CSSProperties} />)}
        <div className="cs-install-emblem"><img src={referencePath(`/brand-assets/delivery/sales-pulse-mark/${resolvedTheme === "dark" ? "dark" : "light"}-background.svg`)} alt="" width="76" height="76" onError={event => { event.currentTarget.hidden = true; }} /><span>✓</span></div>
      </div>
      <Badge tone="success">Sales Pulse Helper is installed</Badge>
      <h1 id="installed-title">Your shop has a<br />new helping hand.</h1>
      <p>More creating. Less checking. Let’s get your Helper ready<br className="cs-install-break" /> to bring your Spoonflower activity into view.</p>
      <div className="cs-install-actions"><Button onClick={start}>Get started</Button><LinkButton variant="ghost" href={referencePath("/?path=/story/products-planned-helper-welcome-and-toolbar--first-visit")} target="_top">Take a look around</LinkButton></div>
      <small>Installed is the first step. Your accounts still need connecting.</small>
    </section>
    <section className="cs-install-setup" aria-label="Set up your Helper">
      <div className="cs-install-steps">{setup.map((item, index) => <button key={item.title} className="cs-install-step" aria-pressed={active === index} onClick={() => setActive(index)}><span className="cs-install-number">0{index + 1}</span><strong>{item.title}</strong><span>{item.summary}</span></button>)}</div>
      {active !== null && <div className="cs-install-guide" ref={guide} tabIndex={-1} aria-label="Setup instructions"><Badge tone="info">Step {active + 1} of 3</Badge><h2>{setup[active]!.title}</h2><p>{setup[active]!.detail}</p>{active < 2 ? <Button variant="secondary" onClick={() => setActive(active + 1)}>Next step</Button> : <LinkButton href={referencePath("/?path=/story/products-planned-helper-welcome-and-toolbar--first-visit")} target="_top">Preview Spoonflower welcome</LinkButton>}<small>Showcase walkthrough · no accounts are connected here.</small></div>}
    </section>
    </div>
    <footer className="cs-install-footer"><span>Make something wonderful. Your Helper is here for the rest.</span><a href={referencePath("/?path=/story/dls-start-here-current-and-planned--overview")} target="_top">Current and planned</a></footer>
  </main>;
}
